def tree_to_dict(root):
    '''
    Helper function to convert XML to Python dictionary.
    '''
    d = {}
    children = list(root)
    if children:
        for child in children:
            child_dict = tree_to_dict(child)
            if child.tag in d:
                if type(d[child.tag]) is list:
                    d[child.tag].append(child_dict)
                else:
                    d[child.tag] = [d[child.tag], child_dict]
            else:
                d[child.tag] = child_dict
    else:
        return root.text

    return d

